-- Versioned generation-model catalog control plane.
--
-- Browser and mobile clients never access these tables. The service role reads
-- the active release and projects the public v1 catalog through application API
-- routes. Published release content is immutable and catalog changes are
-- activated atomically through service-role-only functions.

CREATE TABLE public.generation_models (
  model_id text PRIMARY KEY,
  kind text NOT NULL CHECK (kind IN ('image', 'video', 'motion')),
  created_at timestamptz NOT NULL DEFAULT timezone('utc'::text, now()),
  CONSTRAINT generation_models_id_length_check CHECK (char_length(model_id) BETWEEN 1 AND 120)
);

CREATE TABLE public.generation_model_catalog_releases (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  schema_version integer NOT NULL DEFAULT 1 CHECK (schema_version > 0),
  revision text NOT NULL UNIQUE,
  status text NOT NULL DEFAULT 'draft' CHECK (status IN ('draft', 'shadow', 'active', 'retired')),
  defaults jsonb NOT NULL CHECK (
    jsonb_typeof(defaults) = 'object'
    AND jsonb_typeof(defaults -> 'web') = 'object'
    AND jsonb_typeof(defaults -> 'mobile') = 'object'
  ),
  change_note text NOT NULL DEFAULT '',
  created_by text NOT NULL DEFAULT 'migration',
  activated_at timestamptz,
  retired_at timestamptz,
  created_at timestamptz NOT NULL DEFAULT timezone('utc'::text, now()),
  updated_at timestamptz NOT NULL DEFAULT timezone('utc'::text, now()),
  CONSTRAINT generation_model_catalog_release_revision_check
    CHECK (char_length(revision) BETWEEN 8 AND 128),
  CONSTRAINT generation_model_catalog_release_creator_check
    CHECK (char_length(created_by) BETWEEN 1 AND 200),
  CONSTRAINT generation_model_catalog_release_lifecycle_check
    CHECK (retired_at IS NULL OR activated_at IS NULL OR retired_at >= activated_at)
);

CREATE UNIQUE INDEX generation_model_catalog_one_active_idx
  ON public.generation_model_catalog_releases ((schema_version))
  WHERE status = 'active';

CREATE INDEX generation_model_catalog_release_status_idx
  ON public.generation_model_catalog_releases (status, created_at DESC);

CREATE TABLE public.generation_model_catalog_entries (
  release_id uuid NOT NULL REFERENCES public.generation_model_catalog_releases(id) ON DELETE CASCADE,
  model_id text NOT NULL REFERENCES public.generation_models(model_id) ON DELETE RESTRICT,
  public_descriptor jsonb NOT NULL CHECK (jsonb_typeof(public_descriptor) = 'object'),
  web_enabled boolean NOT NULL DEFAULT true,
  mobile_enabled boolean NOT NULL DEFAULT true,
  adapter_key text NOT NULL CHECK (adapter_key IN ('image-v1', 'video-v1', 'motion-v1')),
  provider_model_map jsonb NOT NULL CHECK (jsonb_typeof(provider_model_map) = 'object'),
  pricing_strategy text NOT NULL CHECK (pricing_strategy IN ('image-v1', 'video-v1', 'motion-v1')),
  pricing_config jsonb NOT NULL CHECK (jsonb_typeof(pricing_config) = 'object'),
  validation_strategy text NOT NULL CHECK (validation_strategy IN ('image-v1', 'video-v1', 'motion-v1')),
  validation_config jsonb NOT NULL DEFAULT '{}'::jsonb CHECK (jsonb_typeof(validation_config) = 'object'),
  verification_config jsonb NOT NULL DEFAULT '{}'::jsonb CHECK (jsonb_typeof(verification_config) = 'object'),
  created_at timestamptz NOT NULL DEFAULT timezone('utc'::text, now()),
  updated_at timestamptz NOT NULL DEFAULT timezone('utc'::text, now()),
  PRIMARY KEY (release_id, model_id)
);

CREATE INDEX generation_model_catalog_entries_model_idx
  ON public.generation_model_catalog_entries (model_id, release_id);

CREATE TABLE public.generation_model_provider_checks (
  id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  release_id uuid NOT NULL,
  model_id text NOT NULL,
  provider text NOT NULL DEFAULT 'kie',
  status text NOT NULL CHECK (status IN ('available', 'changed', 'missing', 'unverifiable', 'error')),
  observed_hash text,
  sanitized_details jsonb NOT NULL DEFAULT '{}'::jsonb CHECK (jsonb_typeof(sanitized_details) = 'object'),
  consecutive_discrepancies integer NOT NULL DEFAULT 0 CHECK (consecutive_discrepancies >= 0),
  checked_at timestamptz NOT NULL DEFAULT timezone('utc'::text, now()),
  FOREIGN KEY (release_id, model_id)
    REFERENCES public.generation_model_catalog_entries(release_id, model_id)
    ON DELETE CASCADE,
  CONSTRAINT generation_model_provider_checks_provider_check
    CHECK (char_length(provider) BETWEEN 1 AND 80)
);

CREATE INDEX generation_model_provider_checks_latest_idx
  ON public.generation_model_provider_checks (release_id, model_id, checked_at DESC);

CREATE OR REPLACE FUNCTION public.generation_model_identity_guard()
RETURNS trigger
LANGUAGE plpgsql
SECURITY INVOKER
SET search_path = public
AS $$
BEGIN
  IF TG_OP = 'DELETE' THEN
    RAISE EXCEPTION 'Generation model identities cannot be deleted';
  END IF;
  IF NEW.model_id IS DISTINCT FROM OLD.model_id OR NEW.kind IS DISTINCT FROM OLD.kind THEN
    RAISE EXCEPTION 'Generation model identity and kind are immutable';
  END IF;
  RETURN NEW;
END;
$$;

CREATE TRIGGER generation_model_identity_guard_trigger
BEFORE UPDATE OR DELETE ON public.generation_models
FOR EACH ROW EXECUTE FUNCTION public.generation_model_identity_guard();

CREATE OR REPLACE FUNCTION public.generation_model_catalog_release_guard()
RETURNS trigger
LANGUAGE plpgsql
SECURITY INVOKER
SET search_path = public
AS $$
BEGIN
  IF OLD.status <> 'draft' AND (
    NEW.schema_version IS DISTINCT FROM OLD.schema_version
    OR NEW.revision IS DISTINCT FROM OLD.revision
    OR NEW.defaults IS DISTINCT FROM OLD.defaults
    OR NEW.change_note IS DISTINCT FROM OLD.change_note
    OR NEW.created_by IS DISTINCT FROM OLD.created_by
  ) THEN
    RAISE EXCEPTION 'Published generation model catalog releases are immutable';
  END IF;
  NEW.updated_at := timezone('utc'::text, now());
  RETURN NEW;
END;
$$;

CREATE TRIGGER generation_model_catalog_release_guard_trigger
BEFORE UPDATE ON public.generation_model_catalog_releases
FOR EACH ROW EXECUTE FUNCTION public.generation_model_catalog_release_guard();

CREATE OR REPLACE FUNCTION public.generation_model_catalog_entry_guard()
RETURNS trigger
LANGUAGE plpgsql
SECURITY INVOKER
SET search_path = public
AS $$
DECLARE
  target_release_id uuid;
  target_status text;
BEGIN
  target_release_id := CASE WHEN TG_OP = 'DELETE' THEN OLD.release_id ELSE NEW.release_id END;
  SELECT status INTO target_status
  FROM public.generation_model_catalog_releases
  WHERE id = target_release_id;

  IF target_status IS DISTINCT FROM 'draft' THEN
    RAISE EXCEPTION 'Only draft generation model catalog releases may be edited';
  END IF;
  IF TG_OP <> 'DELETE' THEN
    NEW.updated_at := timezone('utc'::text, now());
    RETURN NEW;
  END IF;
  RETURN OLD;
END;
$$;

CREATE TRIGGER generation_model_catalog_entry_guard_trigger
BEFORE INSERT OR UPDATE OR DELETE ON public.generation_model_catalog_entries
FOR EACH ROW EXECUTE FUNCTION public.generation_model_catalog_entry_guard();

CREATE OR REPLACE FUNCTION public.publish_generation_model_catalog(
  p_release_id uuid,
  p_expected_active_revision text DEFAULT NULL
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY INVOKER
SET search_path = public
AS $$
DECLARE
  target public.generation_model_catalog_releases%ROWTYPE;
  current_revision text;
  platform_name text;
  kind_name text;
  default_model_id text;
BEGIN
  SELECT * INTO target
  FROM public.generation_model_catalog_releases
  WHERE id = p_release_id
  FOR UPDATE;

  IF target.id IS NULL OR target.status NOT IN ('draft', 'shadow') THEN
    RAISE EXCEPTION 'The target catalog release is not publishable';
  END IF;

  SELECT revision INTO current_revision
  FROM public.generation_model_catalog_releases
  WHERE schema_version = target.schema_version AND status = 'active'
  FOR UPDATE;

  IF p_expected_active_revision IS NOT NULL
    AND current_revision IS DISTINCT FROM p_expected_active_revision THEN
    RAISE EXCEPTION 'The active catalog revision changed';
  END IF;

  IF NOT EXISTS (
    SELECT 1 FROM public.generation_model_catalog_entries WHERE release_id = p_release_id
  ) THEN
    RAISE EXCEPTION 'A catalog release must contain at least one model';
  END IF;

  IF EXISTS (
    SELECT 1
    FROM public.generation_model_catalog_entries entry
    JOIN public.generation_models model ON model.model_id = entry.model_id
    WHERE entry.release_id = p_release_id
      AND (
        entry.public_descriptor ->> 'id' IS DISTINCT FROM entry.model_id
        OR entry.public_descriptor ->> 'kind' IS DISTINCT FROM model.kind
        OR jsonb_typeof(entry.public_descriptor -> 'controls') IS DISTINCT FROM 'array'
        OR jsonb_typeof(entry.public_descriptor -> 'capabilities') IS DISTINCT FROM 'object'
        OR jsonb_typeof(entry.public_descriptor -> 'inputs') IS DISTINCT FROM 'object'
        OR jsonb_object_length(entry.provider_model_map) = 0
      )
  ) THEN
    RAISE EXCEPTION 'One or more catalog entries are invalid';
  END IF;

  FOREACH platform_name IN ARRAY ARRAY['web', 'mobile'] LOOP
    FOREACH kind_name IN ARRAY ARRAY['image', 'video', 'motion'] LOOP
      default_model_id := target.defaults -> platform_name ->> kind_name;
      IF default_model_id IS NULL OR NOT EXISTS (
        SELECT 1
        FROM public.generation_model_catalog_entries entry
        JOIN public.generation_models model ON model.model_id = entry.model_id
        WHERE entry.release_id = p_release_id
          AND entry.model_id = default_model_id
          AND model.kind = kind_name
          AND CASE WHEN platform_name = 'mobile' THEN entry.mobile_enabled ELSE entry.web_enabled END
      ) THEN
        RAISE EXCEPTION 'Invalid % default for %', kind_name, platform_name;
      END IF;
    END LOOP;
  END LOOP;

  UPDATE public.generation_model_catalog_releases
  SET status = 'retired', retired_at = timezone('utc'::text, now())
  WHERE schema_version = target.schema_version AND status = 'active';

  UPDATE public.generation_model_catalog_releases
  SET status = 'active', activated_at = timezone('utc'::text, now()), retired_at = NULL
  WHERE id = p_release_id;

  RETURN jsonb_build_object(
    'status', 'published',
    'releaseId', p_release_id,
    'revision', target.revision,
    'previousRevision', current_revision
  );
END;
$$;

CREATE OR REPLACE FUNCTION public.clone_generation_model_catalog(
  p_source_revision text,
  p_new_revision text,
  p_change_note text,
  p_created_by text
)
RETURNS uuid
LANGUAGE plpgsql
SECURITY INVOKER
SET search_path = public
AS $$
DECLARE
  source_release public.generation_model_catalog_releases%ROWTYPE;
  new_release_id uuid := gen_random_uuid();
BEGIN
  SELECT * INTO source_release
  FROM public.generation_model_catalog_releases
  WHERE revision = p_source_revision;

  IF source_release.id IS NULL THEN
    RAISE EXCEPTION 'The source catalog revision does not exist';
  END IF;
  IF char_length(p_new_revision) NOT BETWEEN 8 AND 128 THEN
    RAISE EXCEPTION 'The new catalog revision is invalid';
  END IF;
  IF NULLIF(btrim(p_created_by), '') IS NULL THEN
    RAISE EXCEPTION 'The catalog creator is required';
  END IF;

  INSERT INTO public.generation_model_catalog_releases (
    id, schema_version, revision, status, defaults, change_note, created_by
  ) VALUES (
    new_release_id,
    source_release.schema_version,
    p_new_revision,
    'draft',
    source_release.defaults,
    COALESCE(p_change_note, ''),
    p_created_by
  );

  INSERT INTO public.generation_model_catalog_entries (
    release_id,
    model_id,
    public_descriptor,
    web_enabled,
    mobile_enabled,
    adapter_key,
    provider_model_map,
    pricing_strategy,
    pricing_config,
    validation_strategy,
    validation_config,
    verification_config
  )
  SELECT
    new_release_id,
    model_id,
    public_descriptor,
    web_enabled,
    mobile_enabled,
    adapter_key,
    provider_model_map,
    pricing_strategy,
    pricing_config,
    validation_strategy,
    validation_config,
    verification_config
  FROM public.generation_model_catalog_entries
  WHERE release_id = source_release.id;

  RETURN new_release_id;
END;
$$;

CREATE OR REPLACE FUNCTION public.rollback_generation_model_catalog(
  p_target_revision text,
  p_expected_active_revision text
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY INVOKER
SET search_path = public
AS $$
DECLARE
  target_id uuid;
  target_schema_version integer;
  current_revision text;
BEGIN
  SELECT id, schema_version INTO target_id, target_schema_version
  FROM public.generation_model_catalog_releases
  WHERE revision = p_target_revision AND status IN ('retired', 'active')
  FOR UPDATE;

  IF target_id IS NULL THEN
    RAISE EXCEPTION 'The rollback catalog revision does not exist';
  END IF;

  SELECT revision INTO current_revision
  FROM public.generation_model_catalog_releases
  WHERE schema_version = target_schema_version AND status = 'active'
  FOR UPDATE;

  IF current_revision IS DISTINCT FROM p_expected_active_revision THEN
    RAISE EXCEPTION 'The active catalog revision changed';
  END IF;

  IF current_revision = p_target_revision THEN
    RETURN jsonb_build_object('status', 'already_active', 'revision', p_target_revision);
  END IF;

  UPDATE public.generation_model_catalog_releases
  SET status = 'retired', retired_at = timezone('utc'::text, now())
  WHERE schema_version = target_schema_version AND status = 'active';

  UPDATE public.generation_model_catalog_releases
  SET status = 'active', activated_at = timezone('utc'::text, now()), retired_at = NULL
  WHERE id = target_id;

  RETURN jsonb_build_object(
    'status', 'rolled_back',
    'revision', p_target_revision,
    'previousRevision', current_revision
  );
END;
$$;

ALTER TABLE public.generation_models ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.generation_model_catalog_releases ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.generation_model_catalog_entries ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.generation_model_provider_checks ENABLE ROW LEVEL SECURITY;

REVOKE ALL ON TABLE public.generation_models FROM PUBLIC, anon, authenticated;
REVOKE ALL ON TABLE public.generation_model_catalog_releases FROM PUBLIC, anon, authenticated;
REVOKE ALL ON TABLE public.generation_model_catalog_entries FROM PUBLIC, anon, authenticated;
REVOKE ALL ON TABLE public.generation_model_provider_checks FROM PUBLIC, anon, authenticated;
REVOKE ALL ON SEQUENCE public.generation_model_provider_checks_id_seq FROM PUBLIC, anon, authenticated;

GRANT SELECT, INSERT, UPDATE, DELETE ON TABLE public.generation_models TO service_role;
GRANT SELECT, INSERT, UPDATE, DELETE ON TABLE public.generation_model_catalog_releases TO service_role;
GRANT SELECT, INSERT, UPDATE, DELETE ON TABLE public.generation_model_catalog_entries TO service_role;
GRANT SELECT, INSERT, UPDATE, DELETE ON TABLE public.generation_model_provider_checks TO service_role;
GRANT USAGE, SELECT ON SEQUENCE public.generation_model_provider_checks_id_seq TO service_role;

REVOKE ALL ON FUNCTION public.generation_model_catalog_release_guard() FROM PUBLIC, anon, authenticated;
REVOKE ALL ON FUNCTION public.generation_model_catalog_entry_guard() FROM PUBLIC, anon, authenticated;
REVOKE ALL ON FUNCTION public.generation_model_identity_guard() FROM PUBLIC, anon, authenticated;
REVOKE ALL ON FUNCTION public.publish_generation_model_catalog(uuid, text) FROM PUBLIC, anon, authenticated;
REVOKE ALL ON FUNCTION public.clone_generation_model_catalog(text, text, text, text) FROM PUBLIC, anon, authenticated;
REVOKE ALL ON FUNCTION public.rollback_generation_model_catalog(text, text) FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION public.generation_model_catalog_release_guard() TO service_role;
GRANT EXECUTE ON FUNCTION public.generation_model_catalog_entry_guard() TO service_role;
GRANT EXECUTE ON FUNCTION public.generation_model_identity_guard() TO service_role;
GRANT EXECUTE ON FUNCTION public.publish_generation_model_catalog(uuid, text) TO service_role;
GRANT EXECUTE ON FUNCTION public.clone_generation_model_catalog(text, text, text, text) TO service_role;
GRANT EXECUTE ON FUNCTION public.rollback_generation_model_catalog(text, text) TO service_role;

DO $catalog_seed$
DECLARE
  seed jsonb := convert_from(decode('', 'base64'), 'utf8')::jsonb;
  seed_release_id uuid := '00000000-0000-4000-8000-000000000101';
BEGIN
  INSERT INTO public.generation_models (model_id, kind)
  SELECT entry.model_id, entry.kind
  FROM jsonb_to_recordset(seed -> 'entries') AS entry(model_id text, kind text)
  ON CONFLICT (model_id) DO NOTHING;

  INSERT INTO public.generation_model_catalog_releases (
    id,
    schema_version,
    revision,
    status,
    defaults,
    change_note,
    created_by,
    activated_at
  )
  VALUES (
    seed_release_id,
    1,
    seed ->> 'revision',
    'draft',
    seed -> 'defaults',
    'Initial release migrated from the verified code catalog.',
    'migration',
    NULL
  )
  ON CONFLICT (id) DO NOTHING;

  INSERT INTO public.generation_model_catalog_entries (
    release_id,
    model_id,
    public_descriptor,
    web_enabled,
    mobile_enabled,
    adapter_key,
    provider_model_map,
    pricing_strategy,
    pricing_config,
    validation_strategy,
    validation_config,
    verification_config
  )
  SELECT
    seed_release_id,
    entry.model_id,
    entry.public_descriptor,
    entry.web_enabled,
    entry.mobile_enabled,
    entry.adapter_key,
    entry.provider_model_map,
    entry.pricing_strategy,
    entry.pricing_config,
    entry.validation_strategy,
    entry.validation_config,
    entry.verification_config
  FROM jsonb_to_recordset(seed -> 'entries') AS entry(
    model_id text,
    public_descriptor jsonb,
    web_enabled boolean,
    mobile_enabled boolean,
    adapter_key text,
    provider_model_map jsonb,
    pricing_strategy text,
    pricing_config jsonb,
    validation_strategy text,
    validation_config jsonb,
    verification_config jsonb
  )
  ON CONFLICT (release_id, model_id) DO NOTHING;

  UPDATE public.generation_model_catalog_releases
  SET
    status = 'active',
    activated_at = timezone('utc'::text, now()),
    updated_at = timezone('utc'::text, now())
  WHERE id = seed_release_id AND status = 'draft';
END;
$catalog_seed$;
